cr=env.cr
def q(s,p=None):
    cr.execute(s,p); return cr.fetchall()
def sec(t): print("\n=====",t)
def tbl(rows,hdr=None):
    if hdr: print(" | ".join(hdr))
    for r in rows: print(" | ".join("" if v is None else (f"{v:,.0f}" if isinstance(v,(int,float)) and not isinstance(v,bool) else str(v)) for v in r))
acc={a.id:(a.code,a.name) for a in env["account.account"].search([])}
sec("Neraca saldo & balance")
print(q("select round(sum(debit)),round(sum(credit)) from account_move_line where parent_state='posted'"))
sec("Rentang & jumlah dokumen")
tbl(q("select move_type,state,count(*),min(date),max(date),round(sum(amount_total)) from account_move group by 1,2 order by 1,2"),["type","state","n","min","max","total"])
tbl(q("select 'SO',state,count(*),min(date_order)::date,max(date_order)::date,round(sum(amount_total)) from sale_order group by 2 union all select 'PO',state,count(*),min(date_order)::date,max(date_order)::date,round(sum(amount_total)) from purchase_order group by 2"),["m","state","n","min","max","total"])
tbl(q("select picking_type_id, pt.name->>'en_US', p.state, count(*) from stock_picking p join stock_picking_type pt on pt.id=p.picking_type_id group by 1,2,3 order by 1,3"),["pt","name","state","n"])
sec("Stok negatif / per lokasi")
tbl(q("select l.complete_name, count(*) filter (where sq.quantity<0), round(sum(sq.quantity)) from stock_quant sq join stock_location l on l.id=sq.location_id where l.usage='internal' group by 1"),["lokasi","n negatif","qty"])
tbl(q("select pp.default_code, l.complete_name, sq.quantity from stock_quant sq join stock_location l on l.id=sq.location_id join product_product pp on pp.id=sq.product_id where l.usage='internal' and sq.quantity<0 order by 3 limit 15"),["sku","lokasi","qty"])
sec("Persediaan GL vs nilai produk")
gl=q("select sum(l.balance) from account_move_line l join account_account a on a.id=l.account_id where l.parent_state='posted' and a.code_store->>'1'='1130101'")[0][0]
pv=sum(env["product.product"].search([("is_storable","=",True)]).mapped("total_value"))
print(f"GL 1130101={gl:,.0f}  Σ total_value produk={pv:,.0f}  selisih={gl-pv:,.0f}")
sec("Saldo akun neraca utama")
tbl(q("select a.code_store->>'1', a.name->>'en_US', round(sum(l.balance)) from account_move_line l join account_account a on a.id=l.account_id where l.parent_state='posted' and a.account_type not like 'income%%' and a.account_type not like 'expense%%' group by 1,2 having abs(sum(l.balance))>0 order by 1"),["kode","akun","saldo"])
sec("Laba rugi per bulan")
tbl(q("select to_char(l.date,'YYYY-MM'), a.account_type, round(sum(-l.balance)) from account_move_line l join account_account a on a.id=l.account_id where l.parent_state='posted' and (a.account_type like 'income%%' or a.account_type like 'expense%%') group by 1,2 order by 1,2"),["bulan","tipe","(+pendapatan/-biaya)"])
sec("Analytic coverage P&L")
tbl(q("select a.account_type, count(*), count(*) filter (where l.analytic_distribution is not null), round(sum(l.balance)), round(coalesce(sum(l.balance) filter (where l.analytic_distribution is not null),0)) from account_move_line l join account_account a on a.id=l.account_id where l.parent_state='posted' and (a.account_type like 'income%%' or a.account_type like 'expense%%') group by 1 order by 1"),["type","baris","beranalytic","saldo","saldo_analytic"])
sec("Item terbuka AR/AP / escrow")
tbl(q("select a.code_store->>'1', a.name->>'en_US', count(*) filter (where not l.reconciled), round(coalesce(sum(l.amount_residual) filter (where not l.reconciled),0)) from account_move_line l join account_account a on a.id=l.account_id where l.parent_state='posted' and a.reconcile group by 1,2 order by 1"),["kode","akun","open","residual"])
sec("Omzet per channel per bulan")
tbl(q("select to_char(so.date_order,'YYYY-MM'), t.name->>'en_US', count(*), round(sum(so.amount_untaxed)), round(sum(so.amount_untaxed)/count(*)) from sale_order so join crm_team t on t.id=so.team_id where so.state='sale' group by 1,2 order by 1,2"),["bulan","channel","orders","dpp","aov"])
sec("Margin kotor per bulan (pendapatan vs HPP)")
tbl(q("select to_char(l.date,'YYYY-MM'), round(sum(-l.balance) filter (where a.account_type='income')), round(sum(l.balance) filter (where a.account_type='expense_direct_cost')) from account_move_line l join account_account a on a.id=l.account_id where l.parent_state='posted' group by 1 order by 1"),["bulan","pendapatan","HPP"])
sec("Margin per SKU (list vs standard_price vs rata2 HPP)")
for p in env["product.product"].search([("sale_ok","=",True),("list_price",">",0)],order="default_code"):
    print(f"{(p.default_code or ''):11s} {p.name[:36]:36s} list={p.list_price:>9,.0f} cost={p.standard_price:>9,.0f} m={(p.list_price-p.standard_price)/p.list_price*100:5.1f}% onhand={p.qty_available:6.0f}")
sec("Bahan baku")
for p in env["product.product"].search([("default_code","like","RM-")]): print(p.default_code,p.qty_available,p.standard_price)
sec("Jurnal & nomor")
tbl(q("select j.code,count(m.*),min(m.name),max(m.name) from account_journal j join account_move m on m.journal_id=j.id and m.state='posted' group by 1 order by 1"),["j","n","min","max"])
sec("Konsistensi: SO->invoice->picking")
print("SO sale tanpa invoice:", q("select count(*) from sale_order where state='sale' and invoice_status<>'invoiced'")[0][0])
print("invoice draft:", q("select count(*) from account_move where state='draft'")[0][0])
print("picking belum done:", q("select state,count(*) from stock_picking where state not in ('done','cancel') group by 1"))
print("MO:", q("select state,count(*) from mrp_production group by 1"))
print("scrap:", q("select count(*), round(sum(scrap_qty)) from stock_scrap"))
sec("Aset")
tbl(q("select name,state,purchase_value,date_start from account_asset order by 1"))
print("kas/bank:", q("select a.code_store->>'1', round(sum(l.balance)) from account_move_line l join account_account a on a.id=l.account_id where a.account_type='asset_cash' and l.parent_state='posted' group by 1 order by 1"))
sec("Hari order (dow) & jam")
tbl(q("select extract(dow from date_order at time zone 'UTC' at time zone 'Asia/Makassar'), count(*) from sale_order where state='sale' group by 1 order by 1"),["dow","n"])
